import{_ as l,a0 as t,w as o,s as d,ao as r,I as p,x as n,a1 as e,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const w=JSON.parse('{"title":"如何識別 Linux 上的文件分身 | LCTT x X-CMD","titleTemplate":false,"description":"如何識別 Linux 上的文件分身 | LCTT (201904) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何識別 Linux 上的文件分身 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何識別 Linux 上的文件分身 | LCTT (201904) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201904/20190415 How to identify duplicate files on Linux","title":"如何識別 Linux 上的文件分身","tag":"201904","desc":""},"relativePath":"201904/20190415 How to identify duplicate files on Linux.md","filePath":"[post].md"}'),h={name:"201904/20190415 How to identify duplicate files on Linux.md"};function c(u,s,g,f,k,m){const a=t("Link");return o(),d("div",null,[s[15]||(s[15]=r(`<h1 id="如何識別-linux-上的文件分身" tabindex="-1">如何識別 Linux 上的文件分身 <a class="header-anchor" href="#如何識別-linux-上的文件分身" aria-label="Permalink to “如何識別 Linux 上的文件分身”">​</a></h1><blockquote><p>Linux 系統上的一些文件可能出現在多個位置。按照本文指示查找並識別這些“同卵雙胞胎”，還可以瞭解為什麼硬鏈接會如此有利。</p></blockquote><p><img src="https://images.idgesg.net/images/article/2019/04/reflections-candles-100793651-large.jpg" alt="Archana Jarajapu CC BY 2.0"></p><p>識別使用同一個磁盤空間的文件依賴於利用文件使用相同的 inode 這一事實。這種數據結構存儲除了文件名和內容之外的所有信息。如果兩個或多個文件具有不同的名稱和文件系統位置，但共享一個 inode，則它們還共享內容、所有權、權限等。</p><p>這些文件通常被稱為“硬鏈接”，不像符號鏈接（即軟鏈接）那樣僅僅通過包含它們的名稱指向其他文件，符號鏈接很容易在文件列表中通過第一個位置的 <code>l</code> 和引用文件的 <code>-&gt;</code> 符號識別出來。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -l my*</span></span>
<span class="line"><span>-rw-r--r-- 4 shs shs   228 Apr 12 19:37 myfile</span></span>
<span class="line"><span>lrwxrwxrwx 1 shs shs     6 Apr 15 11:18 myref -&gt; myfile</span></span>
<span class="line"><span>-rw-r--r-- 4 shs shs   228 Apr 12 19:37 mytwin</span></span></code></pre></div><p>在單個目錄中的硬鏈接並不是很明顯，但它仍然非常容易找到。如果使用 <code>ls -i</code> 命令列出文件並按 inode 編號排序，則可以非常容易地挑選出硬鏈接。在這種類型的 <code>ls</code> 輸出中，第一列顯示 inode 編號。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -i | sort -n | more</span></span>
<span class="line"><span> ...</span></span>
<span class="line"><span> 788000 myfile  &lt;==</span></span>
<span class="line"><span> 788000 mytwin  &lt;==</span></span>
<span class="line"><span> 801865 Name_Labels.pdf</span></span>
<span class="line"><span> 786692 never leave home angry</span></span>
<span class="line"><span> 920242 NFCU_Docs</span></span>
<span class="line"><span> 800247 nmap-notes</span></span></code></pre></div><p>掃描輸出，查找相同的 inode 編號，任何匹配都會告訴你想知道的內容。</p><p>另一方面，如果你只是想知道某個特定文件是否是另一個文件的硬鏈接，那麼有一種方法比瀏覽數百個文件的列表更簡單，即 <code>find</code> 命令的 <code>-samefile</code> 選項將幫助你完成工作。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ find . -samefile myfile</span></span>
<span class="line"><span>./myfile</span></span>
<span class="line"><span>./save/mycopy</span></span>
<span class="line"><span>./mytwin</span></span></code></pre></div><p>注意，提供給 <code>find</code> 命令的起始位置決定文件系統會掃描多少來進行匹配。在上面的示例中，我們正在查看當前目錄和子目錄。</p><p>使用 <code>find</code> 的 <code>-ls</code> 選項添加輸出的詳細信息可能更有説服力：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ find . -samefile myfile -ls</span></span>
<span class="line"><span> 788000    4 -rw-r--r--   4 shs    shs      228 Apr 12 19:37 ./myfile</span></span>
<span class="line"><span> 788000    4 -rw-r--r--   4 shs    shs      228 Apr 12 19:37 ./save/mycopy</span></span>
<span class="line"><span> 788000    4 -rw-r--r--   4 shs    shs      228 Apr 12 19:37 ./mytwin</span></span></code></pre></div><p>第一列顯示 inode 編號，然後我們會看到文件權限、鏈接、所有者、文件大小、日期信息以及引用相同磁盤內容的文件的名稱。注意，在這種情況下，鏈接字段是 “4” 而不是我們可能期望的 “3”。這告訴我們還有另一個指向同一個 inode 的鏈接（但不在我們的搜索範圍內）。</p><p>如果你想在一個目錄中查找所有硬鏈接的實例，可以嘗試以下的腳本來創建列表併為你查找副本：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/bin/bash</span></span>
<span class="line"><span></span></span>
<span class="line"><span># seaches for files sharing inodes</span></span>
<span class="line"><span></span></span>
<span class="line"><span>prev=&quot;&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span># list files by inode</span></span>
<span class="line"><span>ls -i | sort -n &gt; /tmp/$0</span></span>
<span class="line"><span></span></span>
<span class="line"><span># search through file for duplicate inode #s</span></span>
<span class="line"><span>while read line</span></span>
<span class="line"><span>do</span></span>
<span class="line"><span>    inode=\`echo $line | awk &#39;{print $1}&#39;\`</span></span>
<span class="line"><span>    if [ &quot;$inode&quot; == &quot;$prev&quot; ]; then</span></span>
<span class="line"><span>        grep $inode /tmp/$0</span></span>
<span class="line"><span>    fi</span></span>
<span class="line"><span>    prev=$inode</span></span>
<span class="line"><span>done &lt; /tmp/$0</span></span>
<span class="line"><span></span></span>
<span class="line"><span># clean up</span></span>
<span class="line"><span>rm /tmp/$0</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ./findHardLinks</span></span>
<span class="line"><span> 788000 myfile</span></span>
<span class="line"><span> 788000 mytwin</span></span></code></pre></div><p>你還可以使用 <code>find</code> 命令按 inode 編號查找文件，如命令中所示。但是，此搜索可能涉及多個文件系統，因此可能會得到錯誤的結果。因為相同的 inode 編號可能會在另一個文件系統中使用，代表另一個文件。如果是這種情況，文件的其他詳細信息將不相同。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ find / -inum 788000 -ls 2&gt; /dev/null</span></span>
<span class="line"><span> 788000   4 -rw-r--r--   4 shs   shs    228 Apr 12 19:37 /tmp/mycopy</span></span>
<span class="line"><span> 788000   4 -rw-r--r--   4 shs   shs    228 Apr 12 19:37 /home/shs/myfile</span></span>
<span class="line"><span> 788000   4 -rw-r--r--   4 shs   shs    228 Apr 12 19:37 /home/shs/save/mycopy</span></span>
<span class="line"><span> 788000   4 -rw-r--r--   4 shs   shs    228 Apr 12 19:37 /home/shs/mytwin</span></span></code></pre></div><p>注意，錯誤輸出被重定向到 <code>/dev/null</code>，這樣我們就不必查看所有 “Permission denied” 錯誤，否則這些錯誤將顯示在我們不允許查看的其他目錄中。</p><p>此外，掃描包含相同內容但不共享 inode 的文件（即，簡單的文本拷貝）將花費更多的時間和精力。</p><hr>`,23)),p("p",null,[s[1]||(s[1]=n("via: ",-1)),e(a,{href:"https://www.networkworld.com/article/3387961/how-to-identify-duplicate-files-on-linux.html"},{default:i(()=>[...s[0]||(s[0]=[n("https://www.networkworld.com/article/3387961/how-to-identify-duplicate-files-on-linux.html",-1)])]),_:1})]),p("p",null,[s[6]||(s[6]=n("作者：",-1)),e(a,{href:"https://www.networkworld.com/author/Sandra-Henry_Stocker/"},{default:i(()=>[...s[2]||(s[2]=[n("Sandra Henry-Stocker",-1)])]),_:1}),s[7]||(s[7]=n(" 選題：",-1)),e(a,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[3]||(s[3]=[n("lujun9972",-1)])]),_:1}),s[8]||(s[8]=n(" 譯者：",-1)),e(a,{href:"https://github.com/MjSeven"},{default:i(()=>[...s[4]||(s[4]=[n("MjSeven",-1)])]),_:1}),s[9]||(s[9]=n(" 校對：",-1)),e(a,{href:"https://github.com/wxy"},{default:i(()=>[...s[5]||(s[5]=[n("wxy",-1)])]),_:1})]),p("p",null,[s[12]||(s[12]=n("本文由 ",-1)),e(a,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[10]||(s[10]=[n("LCTT",-1)])]),_:1}),s[13]||(s[13]=n(" 原創編譯，",-1)),e(a,{href:"https://linux.cn/"},{default:i(()=>[...s[11]||(s[11]=[n("Linux中國",-1)])]),_:1}),s[14]||(s[14]=n(" 榮譽推出",-1))])])}const x=l(h,[["render",c]]);export{w as __pageData,x as default};
